INSERT INTO cost_codes (work_section_id, cost_code, name, default_unit_id, sort_order)
SELECT ws.id, d.cost_code, d.name, u.id, d.sort_order
FROM (
SELECT '01' section_code,'0101' cost_code,'أعمال التكسير' name,NULL unit_code,1 sort_order UNION ALL
