SELECT '18','1801','أعمال صب وتركيب جي آر سي',NULL,1 UNION ALL SELECT '18','1802','مون ومستلزمات جي آر سي',NULL,2 UNION ALL SELECT '18','1803','نقل ومشال جي آر سي',NULL,3 UNION ALL
SELECT '19','1901','شحن كهرباء ومياه',NULL,1 UNION ALL SELECT '19','1902','إكراميات',NULL,2 UNION ALL SELECT '19','1903','إيجار سقالات',NULL,3 UNION ALL SELECT '19','1904','مشتريات سقالات',NULL,4 UNION ALL SELECT '19','1905','إيجار معدات',NULL,5 UNION ALL SELECT '19','1906','مشتريات براميل',NULL,6 UNION ALL SELECT '19','1907','نقل ومشال',NULL,7 UNION ALL SELECT '19','1908','مواصلات عمالة وانتقالات',NULL,8
) d INNER JOIN work_sections ws ON ws.section_code=d.section_code LEFT JOIN units u ON u.code=d.unit_code
ON DUPLICATE KEY UPDATE cost_code=VALUES(cost_code);
